from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M01','Pensare con i dati','Osservazione, misura e inferenza nelle scienze della Terra')
m.sezione_nuova('Domande e quantità di interesse')
m.pagina('Dalla domanda geologica alla grandezza osservabile',
'''Un confronto fra affioramenti acquista un significato statistico quando vengono precisati la proprietà da misurare, le unità sulle quali osservarla e l’insieme al quale riferire il risultato. Nel caso guida, la densità dei provini permette di formulare una domanda circoscritta, poiché massa e volume sono grandezze registrabili secondo un protocollo. L’espressione «rocce diverse» comprende invece composizione, tessitura, alterazione e numerose altre proprietà, ciascuna delle quali richiederebbe una definizione e un disegno appropriati.''',
'''La domanda adottata riguarda la differenza fra le densità medie dei provini nei due affioramenti. Per interpretarla occorre specificare quali provini appartengano alla popolazione, come siano stati selezionati e in quali condizioni siano state eseguite le misure.''',formula_destra=r'\Delta=\mu_B-\mu_A',richiamo='Il segno del contrasto dipende dall’ordine con cui vengono definiti i gruppi.',origine='M01:11–20')
m.pagina('Descrizione, previsione e spiegazione',
'''La descrizione riassume le osservazioni disponibili; la previsione valuta quanto una procedura riesca ad anticipare valori ancora ignoti, mentre una spiegazione causale attribuisce un cambiamento della risposta a un intervento o a un meccanismo. Benché possano utilizzare le medesime variabili, questi obiettivi richiedono argomenti differenti. Se densità e alterazione risultano associate, la relazione può essere utile per prevedere la densità; per attribuirle un significato causale devono essere considerate anche composizione, storia del campione e modalità di selezione.''',
'''Una previsione viene verificata su unità escluse dalla stima. Un’interpretazione causale richiede invece che le alternative compatibili con il disegno siano esaminate. Nei dati osservazionali del corso, l’affioramento identifica una provenienza: i provini non sono stati assegnati casualmente a un luogo.''',richiamo='Il dominio della conclusione deve corrispondere all’obiettivo effettivamente esaminato.',origine='M01:12–18')
m.pagina('La densità collega due misure dello stesso provino',
'''Poiché la densità è il rapporto fra massa e volume, un aumento della massa può dipendere semplicemente dalle dimensioni del provino. Nel piano massa–volume, le rette passanti per l’origine rappresentano valori costanti del rapporto: a parità di volume, un punto più alto corrisponde a una densità maggiore. La lettura congiunta delle due misure consente quindi di distinguere l’effetto della dimensione da quello della proprietà derivata, purché massa e volume appartengano allo stesso oggetto.''',figura='M01/F01',didascalia='Ventiquattro provini sintetici. Le rette tratteggiate corrispondono a 2,4 e 2,8 g/cm³.',formula=r'\rho_i=\frac{m_i}{V_i},\qquad m_i=\rho_iV_i',richiamo='Un rapporto conserva un significato fisico soltanto quando numeratore e denominatore sono coerenti.',origine='M01:15–18,39')
c=estratto('M01','densita',"d <- read.csv('dati/campioni_modulo1.csv')\nstopifnot(all(d$volume_cm3 > 0))\nd$densita <- d$massa_g / d$volume_cm3\naggregate(densita ~ affioramento, d, mean)")
m.pagina('Conservare l’identità delle osservazioni',
'''L’importazione produce una tabella nella quale ogni riga mantiene insieme identificativo, provenienza e misure del provino. La divisione fra le colonne della massa e del volume avviene posizione per posizione; se una sola colonna fosse stata ordinata separatamente, il programma restituirebbe comunque numeri, ma il rapporto riguarderebbe oggetti differenti. Il controllo del volume precede il calcolo, mentre il raggruppamento successivo produce una tabella di sintesi con una riga per affioramento.''',codice=c,richiamo='Il risultato numerico dipende anche dalle corrispondenze conservate nella tabella.',origine='M01:17–18,94–97')
m.pagina('Formulare un confronto verificabile',
'''Si considerino tre formulazioni: «A e B sono diversi», «la densità è maggiore in B» e «la densità media dei provini accessibili di B supera quella dei provini accessibili di A». Individuare, per ciascuna, quali elementi restino da definire. Specificare poi se il confronto riguardi i provini già raccolti oppure una popolazione più ampia, indicando quale informazione sul campionamento sia necessaria per sostenere il secondo obiettivo.''',
'''La terza formulazione precisa proprietà, sintesi e direzione del contrasto, ma richiede ancora una delimitazione dell’accessibilità e del protocollo di misura. Per descrivere i dati raccolti basta calcolare le due medie; per riferire la differenza alla popolazione occorre giustificare il meccanismo di selezione. La maggiore precisione linguistica rende esplicite queste condizioni.''',richiamo='Una domanda verificabile specifica quantità, unità, dominio e condizioni della misura.',origine='M01:19–20')

m.sezione_nuova('Popolazione e gerarchia del campione')
m.pagina('La popolazione è definita dalla domanda',
'''La popolazione comprende le unità alle quali si intende riferire una proprietà. In un’indagine geologica può essere costituita dai provini estraibili da un affioramento, dalle stazioni di un’area o dalle misure eseguibili in un intervallo temporale. Il campione statistico è il sottoinsieme osservato, mentre il termine «campione» può designare anche un singolo oggetto materiale. Esplicitare questi due usi evita che il conteggio dei pezzi raccolti venga confuso con quello delle unità indipendenti pertinenti all’inferenza.''',
'''Nel caso guida vi sono due affioramenti, tre stazioni per affioramento e quattro provini per stazione. I 24 provini descrivono sei posizioni di campionamento. Ripetere una pesata aumenta il numero delle letture strumentali, lasciando invariato quello dei provini e delle stazioni.''',formula_destra=r'N=\sum_{g=1}^{G}n_g=6\cdot4=24',richiamo='La numerosità pertinente dipende dal livello al quale viene formulata la conclusione.',origine='M01:21–30')
body=n(3.7,.15,'Affioramento A',color='Classical')+rect(.15,.65,7.2,5.7)
for j in range(3):
 x=.4+j*2.35;body+=rect(x,1.15,x+2.05,5.2,'Quantum',5)+n(x+1.025,1.55,'Stazione '+str(j+1),w=2,size=11)
 for k in range(4):body+=n(x+.55+(k%2)*.9,2.75+(k//2)*1.2,r'$\bullet$',color='Classical',size=21)
body+=n(3.7,6.05,'Ogni punto rappresenta un provino',size=10.6)
di=scrivi('M01','D01',body)
m.pagina('Le osservazioni appartengono a livelli distinti',
'''Il diagramma rappresenta uno dei due affioramenti: ciascun contenitore interno identifica una stazione, mentre i punti corrispondono ai provini raccolti nello stesso sito. Questa struttura accompagna il dato anche quando tutte le misure sono memorizzate in un’unica tabella. Se i provini di una stazione condividono condizioni locali, la loro somiglianza deve essere considerata nella valutazione dell’incertezza. La gerarchia descrive pertanto sia l’organizzazione della raccolta sia una possibile struttura di dipendenza.''',tikz=di,didascalia='Schema del disegno: tre stazioni e quattro provini per stazione; le distanze non hanno significato metrico.',richiamo='L’identificativo di stazione conserva un’informazione necessaria per l’analisi.',origine='M01:24–26,65–66')
m.pagina('La media dipende dal peso attribuito alle unità',
'''La media di tutti i provini attribuisce a ciascuna misura lo stesso peso; la media delle medie di stazione attribuisce invece lo stesso peso a ciascun sito. Le due quantità coincidono quando ogni stazione contiene il medesimo numero di provini. Se le numerosità differiscono, la prima espressione pesa maggiormente le stazioni più campionate. La scelta deve quindi essere motivata rispetto alla quantità di interesse, prima di interpretare un eventuale scarto fra i risultati.''',
'''Nel caso bilanciato del corso, ogni stazione contribuisce con quattro provini. La distinzione diventa osservabile duplicando le righe di un sito: la media dei provini cambia, mentre la media delle medie locali rimane invariata. La duplicazione è un esperimento sul peso, privo di nuove informazioni geologiche.''',formula=r'\bar x_{\mathrm{provini}}=\frac{\sum_g n_g\bar x_g}{\sum_g n_g},\\\bar x_{\mathrm{stazioni}}=\frac1G\sum_g\bar x_g',richiamo='Le due medie rispondono a ponderazioni differenti quando i gruppi sono sbilanciati.',origine='M01:25–29,47')
m.pagina('Dati individuali e sintesi locali',
'''I punti mostrano la dispersione dei provini all’interno di ciascuna stazione, mentre i rombi individuano le medie locali. La figura consente di confrontare la variabilità entro sito con gli scarti fra siti, mantenendo visibile la provenienza dei dati. L’addensamento dei punti attorno alla media locale suggerisce una struttura da approfondire; l’incertezza del confronto fra affioramenti richiederà comunque ipotesi sul campionamento delle stazioni e sulla dipendenza fra i provini.''',figura='M01/F02',didascalia='Punti: provini sintetici; rombi: medie di stazione. Lo spostamento orizzontale serve a separare i simboli.',richiamo='La media locale riassume un gruppo, mentre i punti ne documentano l’eterogeneità.',origine='M01:63–66,98–99')
c=estratto('M01','gerarchia',"d <- read.csv('dati/campioni_modulo1.csv')\nd$densita <- d$massa_g / d$volume_cm3\ntable(d$affioramento, d$stazione)\nst <- aggregate(densita ~ stazione, d, mean)\nc(provini=nrow(d), stazioni=nrow(st))\nmean(st$densita)")
m.pagina('Contare unità e ripetizioni',
'''Un gruppo esegue tre pesate su ciascuno dei cinque provini raccolti in quattro stazioni. Si hanno sessanta letture, venti provini e quattro stazioni. Per stimare la ripetibilità della bilancia sono pertinenti le differenze fra pesate dello stesso oggetto; per descrivere la variabilità fra siti occorrono invece confronti fra stazioni. Il codice applica questo principio al dataset del corso, ricostruendo i conteggi dai codici presenti nella tabella.''',codice=c,formula=r'4\ \text{stazioni}\times5\ \text{provini}\times3\ \text{letture}=60',richiamo='Una ripetizione strumentale conserva l’unità materiale sulla quale è stata eseguita.',origine='M01:26,30,58,66')

m.sezione_nuova('Variabili e analisi dimensionale')
m.pagina('La scala di misura delimita le operazioni',
'''Una variabile quantitativa rappresenta una grandezza per la quale le differenze e, quando esiste uno zero fisico pertinente, i rapporti hanno un significato. Una variabile nominale distingue categorie; una variabile ordinale introduce inoltre un ordinamento, senza assicurare distanze uguali fra i livelli. Per questo motivo, la media dei codici assegnati alle litologie dipenderebbe dalla codifica arbitraria. Un identificativo consente infine di riconoscere l’unità, ma le cifre che contiene non ne fanno una misura.''',
'''Massa e volume sono grandezze continue, benché lo strumento le registri con precisione finita. Un conteggio di fossili assume valori interi. Le classi di alterazione possono essere ordinate, purché il protocollo definisca il criterio con cui ogni provino viene assegnato a una classe.''',richiamo='Il tipo informatico della colonna e la scala di misura devono essere controllati separatamente.',origine='M01:31–37,40')
m.pagina('Cambiare unità conserva la grandezza fisica',
'''La conversione della densità richiede di trasformare sia la massa sia il volume. Poiché un grammo corrisponde a un millesimo di chilogrammo e un centimetro cubo a un milionesimo di metro cubo, il rapporto viene moltiplicato per mille. Il numero cambia, mentre la proprietà fisica rimane la stessa. Una colonna che mescoli valori nelle due convenzioni può quindi produrre differenze apparenti molto maggiori dell’eterogeneità geologica che si intende studiare.''',formula=r'1\ \mathrm{g\,cm^{-3}}=\frac{10^{-3}\ \mathrm{kg}}{10^{-6}\ \mathrm{m^3}}=10^3\ \mathrm{kg\,m^{-3}}',figura='M01/F03',didascalia='La medesima densità, 2,68 g/cm³, espressa in due unità. I pannelli hanno scale verticali differenti.',richiamo='Ogni confronto numerico richiede una convenzione di unità comune.',origine='M01:38–39')
m.pagina('Il rapporto di somme e la media dei rapporti',
'''Quando si riuniscono due provini, la densità complessiva deriva dal rapporto fra la massa totale e il volume totale. Sostituendo a ogni massa il prodotto fra densità e volume si ottiene una media ponderata, nella quale i pesi sono i volumi. La media aritmetica delle densità attribuisce invece lo stesso peso a ciascun provino. Le due espressioni coincidono per volumi uguali, ma rispondono a domande differenti quando gli oggetti hanno dimensioni diverse.''',
'''Per due provini con volumi di 10 e 30 cm³ e densità di 2 e 3 g/cm³, la densità complessiva è 2,75 g/cm³. La media delle due densità è 2,5 g/cm³. Entrambi i calcoli sono corretti rispetto alla rispettiva definizione della sintesi.''',formula=r'\rho_{\mathrm{tot}}=\frac{\sum_i m_i}{\sum_iV_i}=\sum_i\frac{V_i}{\sum_jV_j}\rho_i',richiamo='La ponderazione deriva dall’oggetto fisico o statistico che si intende descrivere.',origine='M01:16,38–39,47')
c=estratto('M01','unita',"massa_g <- c(20, 90)\nvolume_cm3 <- c(10, 30)\nrho <- massa_g / volume_cm3\nc(media_provini=mean(rho),\n  densita_complessiva=sum(massa_g)/sum(volume_cm3))\nstopifnot(weighted.mean(rho,volume_cm3)==2.75)")
m.pagina('Verificare la formula su un caso calcolabile',
'''Un esempio ridotto permette di controllare l’implementazione senza dipendere dalla plausibilità del risultato su un dataset ampio. I due provini del codice hanno masse e volumi scelti in modo che il rapporto possa essere ricostruito a mano. Il confronto con la media ponderata verifica una proprietà algebrica della formula. L’esercizio può essere esteso convertendo grammi in chilogrammi e centimetri cubi in metri cubi, per controllare che il risultato segua il fattore di conversione atteso.''',codice=c,richiamo='Un controllo con risposta nota verifica una proprietà specifica del calcolo.',origine='M01:38–40,96')
m.pagina('Riconoscere quantità, categorie e codici',
'''Una tabella contiene identificativo C17, numero di fossili 12, massa 107,2 g, alterazione «alta» e litologia codificata con il valore 3. Stabilire quali trasformazioni conservino il significato di ciascuna colonna. Valutare in particolare se sia ammissibile sommare due conteggi, calcolare una massa media, invertire l’ordine dei livelli di alterazione o interpretare il codice litologico come una quantità tripla rispetto al codice 1.''',
'''La somma dei conteggi richiede unità di raccolta compatibili; la massa media conserva l’unità di misura. Le classi ordinali mantengono l’ordinamento definito dal protocollo, mentre i codici nominali possono essere rinominati senza modificare la classificazione. L’identificativo serve a collegare registrazioni dello stesso provino e deve rimanere univoco.''',richiamo='Le operazioni ammissibili dipendono dal significato della colonna, anche quando tutti i valori sono numerici.',origine='M01:32–40,106–107')

m.sezione_nuova('Disegno della raccolta')
m.pagina('Delimitare la base di campionamento',
'''Per selezionare unità secondo un disegno probabilistico occorre una base che ne permetta l’identificazione. Se alcune porzioni di un affioramento sono irraggiungibili, la popolazione accessibile può differire da quella alla quale si vorrebbe riferire la conclusione. L’aumento della numerosità entro la porzione disponibile riduce soltanto alcune componenti dell’incertezza. Quando l’accessibilità è associata alla proprietà studiata, la copertura incompleta introduce una distorsione che deve essere discussa nel disegno e nell’interpretazione.''',
'''Una carta dei punti raccolti documenta dove si trovino le osservazioni, mentre una descrizione della base chiarisce quali posizioni avrebbero potuto essere selezionate. Queste informazioni sono necessarie per valutare il dominio della conclusione e la presenza di esclusioni sistematiche.''',richiamo='La base effettivamente utilizzata deve essere distinguibile dalla popolazione desiderata.',origine='M01:41–43,62,67')
m.pagina('Tre disegni attribuiscono probabilità diverse',
'''Nel campionamento casuale semplice senza reinserimento, ogni sottoinsieme della numerosità fissata ha uguale probabilità di estrazione. La stratificazione seleziona le unità entro gruppi definiti prima della raccolta. Nel disegno sistematico, una partenza casuale determina posizioni regolarmente distanziate. La scelta richiede di conoscere la struttura del territorio, poiché eventuali periodicità possono interagire con il passo adottato.''',formula=r'\Pr(S=s)=\binom{N}{n}^{-1},\quad |s|=n,\\\pi_i=\Pr(i\in S)=\frac nN',destra='Le formule descrivono il campionamento casuale semplice. Per disegni stratificati o sistematici, probabilità di inclusione e varianza devono essere ricavate dalle rispettive regole di selezione.',richiamo='La casualizzazione deve essere descritta come una procedura effettiva.',origine='M01:44–46')
m.pagina('La selezione modifica la distribuzione',
'''Nel caso simulato, la densità media cresce lungo la coordinata orizzontale. Se la raccolta viene limitata alla porzione iniziale del dominio, le osservazioni disponibili descrivono soprattutto valori più bassi. La figura rende visibile il legame fra posizione, proprietà e selezione, che rimarrebbe nascosto leggendo soltanto il numero dei campioni. L’esempio illustra una possibile distorsione del disegno; la forma del gradiente e la sua intensità sono state definite per l’esercitazione.''',figura='M01/F04',didascalia='Popolazione sintetica di 500 unità. In viola è evidenziata la porzione accessibile, costituita dalle prime 100 posizioni.',richiamo='La rappresentatività richiede un argomento sulla selezione, oltre al conteggio delle osservazioni.',origine='M01:29,42–43,62')
body=rect(.2,.8,5.64,2.2)+rect(5.64,.8,7,2.2,'Quantum')+n(2.9,1.5,'Zona A: 80 unità')+n(6.3,1.5,'B: 20',w=1.2,size=11)+n(3.6,.25,'Popolazione')+n(3.6,3.1,'Campione: 10 unità per zona')+a(2.5,2.35,2.5,2.8)+a(6.2,2.35,5.3,2.8,'Quantum')+n(3.6,4.3,r'$\mu=0{,}8\mu_A+0{,}2\mu_B$')+n(3.6,5.35,'La numerosità campionaria non determina i pesi della popolazione.',w=6.5,size=11)
di=scrivi('M01','D02',body)
m.pagina('La stratificazione separa allocazione e ponderazione',
'''Supponiamo che la popolazione comprenda ottanta unità nella zona A e venti nella zona B, mentre il disegno preveda dieci osservazioni per zona. L’allocazione bilanciata assicura lo stesso numero di misure nei due gruppi, ma la media della popolazione attribuisce loro pesi pari a 0,8 e 0,2. La media semplice delle venti osservazioni attribuirebbe invece peso uguale alle zone. La ponderazione deve quindi conservare la composizione della popolazione che si intende descrivere.''',tikz=di,didascalia='Le larghezze dei rettangoli rappresentano le proporzioni 80% e 20%.',richiamo='I pesi della sintesi devono essere coerenti con l’estimando.',origine='M01:45,47')
m.pagina('Studio osservazionale ed esperimento',
'''In uno studio osservazionale le caratteristiche dei provini vengono registrate nelle condizioni in cui si presentano. In un esperimento, un trattamento può essere assegnato secondo una procedura controllata, così che il confronto sia interpretabile rispetto a tale intervento. Randomizzare il trattamento e selezionare casualmente le unità sono operazioni con funzioni differenti: la prima riguarda la comparabilità dei gruppi sperimentali, la seconda il rapporto fra campione e popolazione.''',
'''Con un vincolo di 24 provini, proporre un disegno che distribuisca la raccolta su più stazioni e registri le condizioni locali. Motivare poi come cambierebbe il piano se la domanda riguardasse l’effetto di un trattamento di laboratorio: il provino diventerebbe un’unità di assegnazione, mentre blocchi e repliche dovrebbero essere definiti prima dell’esperimento.''',richiamo='La randomizzazione del trattamento sostiene un argomento causale entro le condizioni dell’esperimento.',origine='M01:48–50')

m.sezione_nuova('Misura e componenti dell’errore')
m.pagina('La proprietà misurata dipende dal protocollo',
'''Una misura di densità richiede che siano precisati lo stato del provino, il metodo con cui viene determinato il volume e le condizioni ambientali rilevanti. Una densità apparente e una densità dei granuli possono differire perché incorporano porzioni diverse dello spazio poroso. Il protocollo definisce quindi la grandezza effettivamente osservata. Se due gruppi utilizzano procedure differenti, la comparabilità dei risultati deve essere verificata prima di attribuire lo scarto a una differenza fra rocce.''',
'''La risoluzione descrive il più piccolo incremento distinguibile nell’indicazione dello strumento. La ripetibilità riguarda la dispersione di misure eseguite in condizioni specificate. L’accordo con un riferimento richiede inoltre la valutazione delle componenti sistematiche e dell’incertezza del riferimento stesso.''',richiamo='La definizione operativa della misura accompagna il valore e la sua unità.',origine='M01:51–57')
m.pagina('Ripetibilità e distorsione entrano in termini distinti',
'''Un modello elementare rappresenta una lettura come somma del valore del provino, di uno scostamento sistematico e di una componente casuale centrata. Se le componenti casuali delle ripetizioni sono indipendenti e hanno la stessa varianza, la media delle letture ne riduce il contributo alla varianza. Lo scostamento sistematico rimane invece presente nella media. L’uso del modello richiede che il provino e le condizioni della misura restino stabili durante le ripetizioni.''',formula=r'Y_j=\theta+b+\varepsilon_j,\quad\mathbb E(\varepsilon_j)=0,\\\mathbb E(\bar Y)=\theta+b,\quad\operatorname{Var}(\bar Y)=\frac{\sigma_\varepsilon^2}{r}',destra='La formula della varianza presuppone ripetizioni indipendenti. Deriva o dipendenza strumentale introducono termini di covarianza, che verranno sviluppati nel modulo M05.',richiamo='Le ripetizioni stimano la variabilità della misura entro le condizioni in cui vengono effettuate.',origine='M01:53–58')
m.pagina('Ripetere la lettura e cambiare oggetto',
'''Ogni gruppo di punti rappresenta dieci letture dello stesso provino, mentre i quattro gruppi appartengono a oggetti con densità differenti. La dispersione entro gruppo riflette la componente strumentale introdotta nella simulazione; gli scarti fra gruppi rappresentano invece l’eterogeneità fra provini. Se tutte le quaranta letture fossero trattate come osservazioni di quaranta rocce indipendenti, la struttura del disegno verrebbe perduta e l’incertezza del confronto fra oggetti potrebbe risultare sottostimata.''',figura='M01/F05',didascalia='Simulazione: quattro provini, dieci letture per provino e deviazione standard strumentale pari a 0,006.',richiamo='La variabilità strumentale e quella fra oggetti devono essere identificate al rispettivo livello.',origine='M01:54–58,65')
m.pagina('Propagare l’incertezza di massa e volume',
'''La densità dipende da due misure, le cui incertezze si propagano attraverso il rapporto. Linearizzando la funzione attorno ai valori di riferimento, il contributo della massa è proporzionale all’inverso del volume, mentre quello del volume cresce con la massa e con l’inverso del volume al quadrato. Un’eventuale covarianza modifica il risultato. L’approssimazione è appropriata quando le incertezze sono abbastanza piccole da rendere trascurabili i termini di ordine superiore.''',formula=r'\frac{\partial\rho}{\partial m}=\frac1V,\qquad\frac{\partial\rho}{\partial V}=-\frac m{V^2},\\u_\rho^2\approx\frac{u_m^2}{V^2}+\frac{m^2u_V^2}{V^4}-\frac{2m}{V^3}\operatorname{Cov}(m,V)',destra='Per misure indipendenti il termine di covarianza si annulla. L’incertezza relativa del volume può dominare il risultato anche quando la bilancia fornisce letture molto stabili.',richiamo='L’incertezza di una grandezza derivata dipende dalla sensibilità della formula agli ingressi.',origine='M01:57–59; approfondimento formale')
c=estratto('M01','controlli',"densita <- function(massa,volume) {\n stopifnot(length(massa)==length(volume))\n stopifnot(all(is.finite(massa)),\n           all(is.finite(volume)))\n stopifnot(all(massa>0), all(volume>0))\n massa / volume\n}\nstopifnot(densita(107.2,40)==2.68)")
m.pagina('Distinguere un vincolo fisico da una soglia empirica',
'''Un volume nullo rende indefinito il rapporto usato per la densità, mentre una massa negativa è incompatibile con il protocollo considerato. Questi vincoli differiscono da una soglia empirica applicata a valori ritenuti insoliti, poiché un valore raro può rappresentare una proprietà reale del campione. La funzione controlla condizioni esplicite sugli ingressi e interrompe il calcolo quando non sono soddisfatte. La decisione sulla causa dell’anomalia richiede comunque il confronto con scheda e misura originali.''',codice=c,richiamo='Il controllo segnala l’incompatibilità; la correzione richiede un’evidenza sulla causa.',origine='M01:59–60,86')

m.sezione_nuova('Dipendenza e confondimento')
m.pagina('La posizione e il tempo appartengono al dato',
'''Due raccolte con la medesima numerosità possono fornire informazioni differenti se una copre molte stazioni e l’altra concentra le osservazioni in un’unica posizione. Analogamente, letture ravvicinate di un sensore possono condividere condizioni che persistono nel tempo. Coordinate, date e identificativi dei gruppi permettono di riconoscere queste strutture. La dipendenza diventa rilevante quando la valutazione dell’incertezza utilizza informazioni che più osservazioni hanno in comune, come se fossero contributi distinti.''',
'''Nel caso spaziale, provini vicini possono condividere composizione e storia di alterazione. Nel caso temporale, una sequenza può risentire della memoria del processo o dello strumento. L’ordinamento e la posizione devono quindi essere conservati anche quando la prima analisi utilizza soltanto distribuzioni e medie.''',richiamo='La tabella analitica deve conservare le informazioni necessarie a ricostruire il disegno.',origine='M01:61–67')
body=n(3.6,.4,'Condizioni del sito',w=3,color='Quantum')+n(1.4,3,'Alterazione',w=2.5)+n(5.9,3,'Densità',w=2.3)+a(2.7,1.1,1.5,2.5,'Quantum')+a(4.5,1.1,5.8,2.5,'Quantum')+linea(2.7,3,4.7,3,'Muted')+n(3.7,4.8,'L’associazione osservata può includere una causa comune.',w=6.2)
di=scrivi('M01','D03',body)
m.pagina('Una causa comune può generare un’associazione',
'''L’alterazione e la densità possono entrambe dipendere da caratteristiche del sito, come composizione mineralogica, porosità e storia di esposizione. In tal caso, una differenza di densità fra classi di alterazione comprende più contributi compatibili con i dati. Il diagramma rappresenta un’ipotesi qualitativa da discutere, nella quale le condizioni locali influenzano entrambe le variabili. Le frecce esplicitano la struttura proposta; la loro validità richiede conoscenze e osservazioni ulteriori.''',tikz=di,didascalia='Schema causale ipotetico. Il segmento inferiore segnala l’associazione osservabile e non una relazione causale identificata.',richiamo='Un diagramma causale rende esplicite le ipotesi che sostengono l’interpretazione.',origine='M01:14,48,68')
m.pagina('Confrontare entro condizioni osservate',
'''La figura conserva l’affioramento di provenienza e distingue le classi di alterazione, permettendo di osservare se la composizione dei gruppi differisca. Un confronto aggregato può risentire sia degli scarti entro classe sia della diversa frequenza delle classi nei due affioramenti. La stratificazione descrittiva rende visibile questa possibilità, ma eventuali classi poco rappresentate e fattori non misurati continuano a limitare l’interpretazione. Il dataset sintetico serve a esercitare questa lettura condizionata.''',figura='M01/F06',didascalia='Densità dei 24 provini, distinta per alterazione e affioramento. Le categorie derivano dal protocollo didattico.',richiamo='La composizione dei gruppi può contribuire alla differenza fra le loro medie aggregate.',origine='M01:68,75')
m.pagina('La covarianza modifica l’informazione della media',
'''La varianza della media contiene le varianze individuali e le covarianze fra osservazioni. Quando queste ultime sono positive, l’ipotesi di indipendenza trascura una componente dell’incertezza. Il modello con varianze uguali e correlazione comune mostra come l’effetto cresca con la dimensione del gruppo. La correlazione e l’adeguatezza del modello devono essere giustificate nel caso applicativo, come verrà sviluppato in M05.''',formula=r'\operatorname{Var}(\bar X)=\frac1{n^2}\left[\sum_i\sigma_i^2+2\sum_{i<j}\operatorname{Cov}(X_i,X_j)\right],\\\operatorname{Var}(\bar X)=\frac{\sigma^2}{n}[1+(n-1)\eta]',destra='La seconda espressione riguarda un solo gruppo equicorrelato. Se la correlazione comune è positiva, la precisione cresce più lentamente di quanto previsto dal modello indipendente.',richiamo='La numerosità delle righe deve essere interpretata insieme alla loro dipendenza.',origine='M01:63–66; raccordo con M05')
m.pagina('Interpretare un cambiamento nella serie',
'''Una stazione registra un salto persistente nella concentrazione di una sostanza. Prima di attribuirlo a un cambiamento ambientale, occorre verificare se nello stesso periodo siano mutati sensore, calibrazione, posizione, frequenza o procedura di elaborazione. La coincidenza temporale fra una modifica del protocollo e il salto rende plausibile una spiegazione strumentale, senza dimostrarla da sola. La valutazione richiede registri di manutenzione, eventuali misure sovrapposte e confronti con stazioni comparabili.''',
'''Per l’esercizio, predisporre una tabella che associ a ogni ipotesi l’informazione necessaria a valutarla. Una sovrapposizione fra vecchio e nuovo strumento può stimare uno scostamento; una stazione di confronto può documentare una variazione comune. In assenza di tali informazioni, la conclusione deve conservare l’ambiguità fra processo e misura.''',richiamo='I metadati temporali permettono di distinguere cambiamenti del fenomeno e del sistema di osservazione.',origine='M01:64,69–70')

m.sezione_nuova('Dalla raccolta alla conclusione')
m.pagina('Il protocollo collega domanda e procedura',
'''Un protocollo specifica la quantità di interesse, le unità da osservare, il disegno della raccolta, le condizioni della misura e le regole di trattamento dei dati. Definirlo prima dell’analisi permette di distinguere le decisioni previste dalle modifiche suggerite dai risultati. Le modifiche possono essere necessarie, purché ne siano documentati motivo e conseguenze. Questa distinzione rende ricostruibile il percorso attraverso il quale una conclusione è stata ottenuta.''',
'''Nel caso guida, il protocollo registra affioramento e stazione, conserva massa e volume originali, verifica valori e identificativi, deriva la densità e presenta i punti insieme alle sintesi. Il confronto inferenziale viene rinviato finché non siano dichiarate le ipotesi sulla selezione e sulla dipendenza.''',richiamo='Ogni trasformazione deve essere motivata rispetto alla domanda e al significato delle variabili.',origine='M01:71–74,76–80')
body=rect(.2,.6,3,1.9)+n(1.6,1.25,'Misure originali',w=2.5)+rect(4.2,.6,7,1.9,'Quantum')+n(5.6,1.25,'Protocollo e dizionario',w=2.5)+a(1.6,2.1,2.9,3)+a(5.6,2.1,4.3,3,'Quantum')+rect(2.1,3,5.1,4.2)+n(3.6,3.6,'Tabella analitica',w=2.7)+a(3.6,4.4,3.6,5)+n(3.6,5.5,'Sintesi e conclusione',w=5.8)
di=scrivi('M01','D04',body)
m.pagina('Le trasformazioni devono avere una provenienza',
'''La tabella analitica viene costruita applicando alle misure originali regole dichiarate nel protocollo e nel dizionario. Il diagramma evidenzia che il risultato dipende da entrambe le componenti: una stessa tabella grezza può produrre sintesi differenti se cambiano unità, filtri o definizioni delle variabili. Conservare sorgenti e regole consente di ricostruire tali differenze. Gli output vengono quindi trattati come prodotti rigenerabili, associati alla versione degli input e del codice.''',tikz=di,didascalia='Dipendenze logiche fra misure, definizioni, trasformazioni e risultati.',richiamo='La provenienza comprende i dati acquisiti e le decisioni che ne determinano l’uso.',origine='M01:72–74,79–80')
m.pagina('Esaminare la sensibilità a una scelta analitica',
'''L’applicazione di una soglia minima al volume modifica il sottoinsieme dei provini inclusi nel calcolo. La figura mostra come vari la media della densità quando cambia questa soglia, senza attribuire alle oscillazioni un significato inferenziale. Un filtro può essere giustificato da un limite del protocollo, ma il suo effetto deve essere reso visibile. Se la conclusione varia sensibilmente entro un insieme di scelte plausibili, tale dipendenza appartiene alla discussione del risultato.''',figura='M01/F07',didascalia='Analisi di sensibilità sui dati sintetici: media dei provini con volume almeno pari alla soglia indicata.',richiamo='La scelta della soglia deve precedere l’interpretazione favorevole di un risultato.',origine='M01:78,80')
m.pagina('L’audit conserva evidenza e decisione',
'''Durante l’audit vengono controllati dimensioni della tabella, tipi delle colonne, identificativi, disponibilità delle misure e compatibilità fisica dei valori. Un’anomalia viene registrata con il relativo codice di unità, così che possa essere confrontata con la fonte. La tabella grezza rimane il riferimento per distinguere ciò che è stato osservato da ciò che è stato corretto o escluso. Il registro delle decisioni collega ogni intervento alla sua motivazione e permette di valutarne l’effetto.''',
'''Se tre valori elevati vengono rimossi, il registro deve indicare quali siano, quale evidenza giustifichi l’esclusione e come cambi la sintesi includendoli. Una cancellazione motivata soltanto dal desiderio di ottenere una relazione più regolare renderebbe la procedura dipendente dall’esito atteso.''',richiamo='Un valore insolito richiede un’indagine sulla sua origine prima di una decisione analitica.',origine='M01:73–80,86')
m.pagina('Scrivere una conclusione proporzionata ai dati',
'''Una conclusione scientifica riporta la quantità stimata nelle sue unità, identifica le osservazioni e il dominio al quale si riferisce, ed esplicita le condizioni che sostengono eventuali generalizzazioni. Nel caso guida è possibile descrivere le densità dei ventiquattro provini simulati; l’estensione a tutti i provini dei due affioramenti richiederebbe una giustificazione del disegno. La distinzione evita che una differenza descrittiva venga presentata come una proprietà universale o come una spiegazione causale.''',
'''Una formulazione appropriata può riportare le medie dei due gruppi e la loro differenza, precisando che il confronto riguarda il campione didattico. L’aggiunta di un intervallo richiederà una procedura inferenziale coerente con le stazioni e con le ipotesi di selezione, sviluppata nei moduli successivi.''',richiamo='Quantità, unità, dominio e condizioni rendono interpretabile una conclusione.',origine='M01:77,103')

m.sezione_nuova('Metadati, disponibilità e censura')
m.pagina('Il dizionario rende interpretabile una colonna',
'''Il nome di una variabile offre soltanto un’indicazione sintetica. Il dizionario ne precisa definizione, unità, tipo, categorie ammissibili e convenzioni per i valori mancanti, indicando inoltre come sia stata misurata o derivata. Per le variabili calcolate occorre conservare la formula e i riferimenti agli ingressi. La provenienza del dataset completa questa descrizione con autore o ente, versione, data di acquisizione, condizioni di riuso e trasformazioni già applicate.''',
'''La colonna della densità viene definita come rapporto fra massa in grammi e volume in centimetri cubi. I codici degli affioramenti e delle stazioni conservano la struttura del disegno. Le categorie di alterazione richiedono una descrizione del criterio osservativo con cui sono state assegnate.''',richiamo='Il dizionario accompagna il file affinché le colonne possano essere interpretate fuori dal contesto di chi le ha create.',origine='M01:81–83,88')
m.pagina('Un dato censurato fornisce un vincolo',
'''Una registrazione inferiore al limite di rilevabilità comunica che il valore appartiene a un intervallo compatibile con il metodo, senza identificarne la posizione esatta. Sostituirla con il limite trasformerebbe questa informazione in una misura puntuale; sostituirla con zero introdurrebbe un’altra ipotesi. Un dato mancante, invece, può non fornire alcun vincolo quantitativo. Le tre condizioni devono essere conservate separatamente, insieme al motivo della mancata osservazione e al limite applicabile.''',formula=r'X<L\quad\Rightarrow\quad X\in[0,L)\ \text{se }X\ge0',figura='M01/F08',didascalia='Esempio schematico: misura puntuale, intervallo di censura e valore mancante. La barra rappresenta valori possibili, non una distribuzione.',richiamo='Il trattamento analitico della censura deve utilizzare l’informazione effettivamente disponibile.',origine='M01:84–85')
m.pagina('La disponibilità può dipendere dal fenomeno',
'''Un sensore può interrompersi nelle condizioni più estreme, oppure un archivio può conservare più facilmente campioni integri rispetto a quelli fragili. In entrambi i casi, l’insieme disponibile può avere una composizione differente da quella iniziale. Il confronto fra dati presenti e assenti richiede quindi informazioni sul processo di acquisizione e conservazione. Riportare soltanto il numero dei mancanti descrive la disponibilità, mentre la valutazione della distorsione richiede un argomento sul meccanismo che li ha generati.''',
'''Se la densità dei provini mancanti è associata alla probabilità di rottura, la media dei campioni conservati può descrivere soprattutto una componente della popolazione. Una maggiore numerosità fra i campioni integri lascia irrisolta questa selezione.''',formula_destra=r'\mathbb E(X\mid R=1)\ \text{può differire da}\ \mathbb E(X)',richiamo='R indica la disponibilità della misura: il suo rapporto con X deve essere considerato.',origine='M01:67,84–85')
m.pagina('La rappresentazione deve conservare le quantità',
'''Assi, unità, simboli e colori determinano quali confronti una figura renda immediatamente percepibili. Se l’area di un simbolo rappresenta una quantità, il raggio deve crescere con la radice quadrata di tale quantità; proporzionare direttamente il raggio ne amplificherebbe visivamente i rapporti. La leggibilità richiede inoltre che numeri, etichette e legenda rimangano distinguibili nelle dimensioni effettive della slide. La scelta grafica deve essere spiegabile rispetto alla grandezza rappresentata.''',formula=r'A=\pi r^2,\qquad r\propto\sqrt q\quad\text{se }A\propto q',destra='Un asse troncato può essere appropriato per osservare variazioni piccole, purché il limite sia evidente e il lettore possa ricostruire la scala. Le barre usano la lunghezza per codificare una quantità e richiedono particolare attenzione allo zero.',richiamo='La geometria della figura deve corrispondere alla codifica dichiarata.',origine='M01:87')
m.pagina('Documentare gli strumenti automatici',
'''Un suggerimento automatico può accelerare la scrittura di codice o la ricerca di un errore, ma il risultato deve essere controllato sulle definizioni del problema, sulla documentazione delle funzioni e su esempi con risposta nota. La responsabilità dell’interpretazione rimane legata alle evidenze disponibili. Quando uno strumento ha contribuito alla procedura, il suo uso può essere documentato insieme alle verifiche eseguite, preservando dati riservati, condizioni di licenza e attribuzione delle fonti.''',
'''Prima della consegna, verificare che un lettore possa identificare input, codice, dipendenze e risultati. Una citazione documenta l’origine di un metodo o di un dataset; la verifica numerica controlla una proprietà dell’implementazione. Le due operazioni sostengono aspetti differenti della tracciabilità.''',richiamo='Fonti e verifiche rendono valutabile il percorso seguito per ottenere il risultato.',origine='M01:88–90')

m.sezione_nuova('Il primo laboratorio in R')
m.pagina('Il progetto conserva il percorso dell’analisi',
'''L’esecuzione parte dalla cartella del progetto, nella quale dati, sorgenti e risultati hanno percorsi relativi riconoscibili. La console permette di esaminare un’espressione; lo script conserva la sequenza che deve ricostruire l’analisi. Per questo motivo, il laboratorio viene verificato dopo il riavvio della sessione, quando gli oggetti creati durante prove precedenti non sono più disponibili. Le istruzioni devono caricare gli input necessari e produrre gli output nell’ordine previsto.''',
'''Aprire il progetto distribuito, individuare il CSV dei provini e leggere il dizionario. Eseguire quindi lo script del laboratorio dall’inizio. L’uso dei percorsi relativi permette di trasferire l’intera cartella senza introdurre riferimenti al nome utente o alla posizione del computer di origine.''',richiamo='Una sessione pulita verifica che il codice dichiari le proprie dipendenze operative.',origine='M01:91–95,100')
c=estratto('M01','audit',"d <- read.csv('dati/campioni_modulo1.csv')\nstopifnot(nrow(d)==24L)\nstopifnot(anyDuplicated(d$id)==0L)\nstr(d)\ncolSums(is.na(d))\ntable(d$affioramento,d$stazione)")
m.pagina('Verificare forma, chiavi e disponibilità',
'''Il numero delle righe, l’unicità degli identificativi e i tipi delle colonne costituiscono controlli complementari. Una tabella di 24 righe potrebbe infatti contenere un provino duplicato e un altro mancante, pur conservando la numerosità attesa. Il conteggio per stazione permette di confrontare la tabella con il disegno previsto, mentre il riepilogo dei valori mancanti documenta quali misure siano disponibili. Questi controlli precedono il calcolo della densità e delle sintesi.''',codice=c,richiamo='La numerosità corretta è necessaria, ma l’integrità del campione richiede anche il controllo delle chiavi.',origine='M01:94–96')
m.pagina('Mostrare il confronto conservando le osservazioni',
'''La figura presenta le densità dei provini per affioramento e sovrappone la media di ciascun gruppo. La dispersione dei punti permette di valutare quanto una differenza fra medie coesista con l’eterogeneità interna e con la sovrapposizione delle distribuzioni. La lettura resta descrittiva, poiché l’incertezza della differenza dipende dal disegno a stazioni. Un grafico con sole barre delle medie renderebbe meno visibili questi elementi del campione.''',figura='M01/F09',didascalia='Provini sintetici distinti per affioramento; i rombi rappresentano le medie. Il lieve spostamento orizzontale separa i simboli.',richiamo='Una sintesi grafica può essere affiancata dai valori individuali che la determinano.',origine='M01:97–99')
c=estratto('M01','esporta',"d <- read.csv('dati/campioni_modulo1.csv')\nd$densita <- d$massa_g / d$volume_cm3\ndir.create('risultati',showWarnings=FALSE)\nf <- 'risultati/provini_con_densita.csv'\nwrite.csv(d,f,row.names=FALSE)\nr <- read.csv(f)\nstopifnot(identical(r$id,d$id))\nstopifnot(isTRUE(all.equal(r$densita,d$densita)))")
m.pagina('L’esportazione viene controllata rileggendo il file',
'''Un oggetto presente nella memoria della sessione diventa un risultato trasferibile quando viene scritto in un formato documentato. La rilettura del file verifica che identificativi e valori siano conservati attraverso l’esportazione. Il controllo deve ammettere una tolleranza appropriata quando il formato testuale modifica la rappresentazione numerica. Nel laboratorio, la tabella derivata contiene la nuova colonna della densità, mentre il file originale rimane disponibile per ricostruire il calcolo.''',codice=c,richiamo='La rilettura collega il risultato presente in memoria al file effettivamente consegnato.',origine='M01:100')
m.pagina('La consegna rende ricostruibile il confronto',
'''La scheda di laboratorio deve presentare la domanda, descrivere i provini e le stazioni, riportare la formula della densità e mostrare il confronto fra affioramenti. Tabelle e figure vengono accompagnate dalle unità, dalla natura sintetica dei dati e dalle condizioni che limitano l’interpretazione. Il codice deve permettere a un altro lettore di riprodurre gli stessi valori partendo dagli input inclusi, senza ricostruire manualmente passaggi avvenuti nella console.''',
'''Una consegna completa comprende lo script, la tabella derivata, una figura con i punti, le medie descrittive e una breve discussione del disegno. La verifica consiste nel ripetere l’esecuzione da una cartella estratta e nel confrontare i risultati con quelli riportati nella scheda.''',richiamo='La riproducibilità viene valutata sulla procedura e sui file consegnati.',origine='M01:101–103')

m.sezione_nuova('Confronto dei disegni e verifica finale')
m.pagina('La stessa numerosità può produrre errori differenti',
'''La simulazione ripete la raccolta di 24 provini dalla popolazione con gradiente già esaminata. Nel disegno casuale ogni posizione appartiene alla base di selezione; nel disegno accessibile le estrazioni riguardano soltanto la porzione iniziale. Le distribuzioni delle medie permettono di distinguere la variabilità fra ripetizioni dallo scostamento rispetto alla media della popolazione. Una distribuzione stretta può quindi essere concentrata attorno a un valore che descrive soltanto il dominio selezionato.''',figura='M01/F10',didascalia='Duemila campioni per disegno, ciascuno di 24 unità. La linea verticale indica la media della popolazione sintetica.',richiamo='Precisione e corrispondenza con la popolazione richiedono valutazioni distinte.',origine='M01:104–105')
m.pagina('Ponderazione di zone con densità differenti',
'''Una popolazione comprende una zona che contiene l’80% delle unità e ha densità media 2,4, e una seconda zona che contiene il restante 20% e ha media 3,0. Il campionamento raccoglie lo stesso numero di provini nelle due zone. Calcolare la media della popolazione e la media ottenuta attribuendo uguale peso ai due gruppi campionati. Spiegare poi quale informazione aggiuntiva renda possibile passare dalla seconda alla prima.''',formula=r'\mu=0{,}8\cdot2{,}4+0{,}2\cdot3{,}0=2{,}52,\\\frac{2{,}4+3{,}0}{2}=2{,}70',destra='La media della popolazione richiede i pesi delle zone. L’allocazione bilanciata dei provini serve a ottenere informazioni in entrambi i gruppi; la sintesi complessiva deve ripristinare la composizione pertinente alla domanda.',richiamo='L’allocazione delle osservazioni e la definizione della media sono decisioni collegate ma distinte.',origine='M01:47,104–107')
m.pagina('Verifica delle condizioni necessarie',
'''Valutare le seguenti conclusioni specificando quali informazioni le renderebbero sostenibili: un codice litologico maggiore indica una quantità maggiore; cento pesate dello stesso provino descrivono cento rocce; una media precisa rappresenta l’intero affioramento; una differenza fra siti dimostra l’effetto dell’alterazione. Per ogni caso, distinguere l’errore di definizione dalla mancanza di un’ipotesi sul disegno o sul processo.''',
'''I codici nominali identificano classi; le ripetizioni descrivono la misura sullo stesso oggetto; la rappresentatività dipende dalla selezione; l’attribuzione causale richiede che siano considerate spiegazioni alternative. La correzione consiste nel riformulare la conclusione al livello effettivamente sostenuto dalle osservazioni e dal disegno.''',richiamo='Le condizioni mancanti devono essere esplicitate nella conclusione corretta.',origine='M01:106–107')
m.pagina('Raccordo con gestione dei dati e inferenza',
'''Il modulo successivo sviluppa le operazioni che trasformano misure e metadati in una tabella analitica, mantenendo chiavi, unità e disponibilità. La statistica descrittiva renderà poi più precisa la lettura delle distribuzioni, mentre probabilità e campionamento forniranno gli strumenti per valutare l’incertezza. Questi sviluppi utilizzano le distinzioni già introdotte fra oggetto, lettura strumentale, stazione, popolazione e quantità di interesse.''',
'''Nel proseguire, mantenere una domanda ricorrente: quale insieme di unità viene rappresentato dalla quantità appena calcolata? La risposta permette di riconoscere quando un’operazione modifica il livello della tabella, la ponderazione della sintesi o il dominio della conclusione.''',richiamo='Le definizioni delle unità e delle grandezze vengono riutilizzate lungo l’intero corso.',origine='M01:110')
m.sezione_nuova('Fonti e materiali')
m.pagina('Riferimenti per definizioni, misura e dati',
'''Le definizioni statistiche sono sviluppate attraverso il caso dei provini e gli esempi sintetici inclusi. Per il lessico metrologico, il riferimento è il Vocabolario internazionale di metrologia del JCGM; per la propagazione dell’incertezza si considera l’approssimazione al primo ordine descritta nella Guide to the Expression of Uncertainty in Measurement. I materiali didattici distinguono tale modello dall’analisi empirica della variabilità fra provini e fra stazioni.''',
r'''JCGM 200:2012, International Vocabulary of Metrology.\par\medskip JCGM 100:2008, Evaluation of measurement data — Guide to the expression of uncertainty in measurement.\par\medskip R Core Team, An Introduction to R e documentazione delle funzioni utilizzate.\par\medskip Dati del corso: campioni sintetici, dizionario e provenienza inclusi.''',richiamo='I riferimenti completi e gli indirizzi delle risorse sono raccolti nel registro delle fonti.',fonti='JCGM; R; CORSO',origine='M01:108–109')
body=n(3.7,.3,'Due misure dello stesso oggetto',w=6.8)
body+=r'\draw[Classical,fill=Classical!12,line width=1pt] (2.8,1.5)--(4.15,1.1)--(4.7,2.15)--(3.85,2.95)--(2.55,2.5)--cycle;'
body+=a(2.6,3.05,1.6,3.7)+a(4.6,3.05,5.7,3.7,'Quantum')+n(1.6,4.2,r'$m$ in grammi',w=2.6)+n(5.7,4.2,r'$V$ in cm$^3$',w=2.6)+n(3.7,5.55,r'$\rho=m/V$')
di=scrivi('M01','D05',body)
m.inserisci_dopo('La densità collega due misure dello stesso provino',titolo='Due misure dello stesso provino',testo='''Il disegno associa massa e volume a un unico provino, rendendo esplicita la corrispondenza necessaria al rapporto. Se la massa di un oggetto venisse divisa per il volume di un altro, la formula sarebbe eseguibile ma perderebbe la propria definizione fisica. L’identificativo deve quindi attraversare acquisizione, registrazione e trasformazione. Nei laboratori successivi, il controllo delle chiavi svolgerà questa funzione quando le misure provengono da file differenti.''',tikz=di,didascalia='Sagoma illustrativa; masse e volumi devono riferirsi allo stesso oggetto e allo stesso stato del provino.',richiamo='La correttezza algebrica richiede corrispondenze coerenti fra gli ingressi.',origine='M01:17–18,39')
body=n(3.7,.3,'Contributi alla media complessiva')
body+=rect(.4,1.1,2.05,3.4)+rect(2.05,1.1,7,3.4,'Quantum')+n(1.22,2.2,'10',w=1.4)+n(4.5,2.2,'30',w=3)+n(1.22,4.1,r'$\rho_1=2$',w=2)+n(4.5,4.1,r'$\rho_2=3$',w=3)+n(3.7,5.4,r'$\rho_{\rm tot}=\tfrac14\cdot2+\tfrac34\cdot3=2{,}75$')
di=scrivi('M01','D06',body)
m.inserisci_dopo('Il rapporto di somme e la media dei rapporti',titolo='Il volume determina i pesi della densità complessiva',testo='''Le due regioni hanno larghezze nel rapporto uno a tre, corrispondente ai volumi dell’esempio. La densità complessiva attribuisce quindi un quarto del peso al primo provino e tre quarti al secondo. La rappresentazione consente di ricostruire la ponderazione direttamente dalla grandezza estensiva conservata nell’aggregazione. Quando si descrive il provino medio, invece, il peso di ciascun oggetto è uguale e la quantità di interesse cambia.''',tikz=di,didascalia='Le aree rappresentano volumi di 10 e 30 cm³; le densità sono espresse in g/cm³.',richiamo='La geometria del diagramma rappresenta i pesi, mentre le etichette riportano le densità.',origine='M01:38–39,47')
body=n(1.9,.3,'Casuale',color='Classical')+n(5.6,.3,'Sistematico',color='Quantum')+rect(.2,.9,3.5,4.8)+rect(3.9,.9,7.2,4.8,'Quantum')
for x,y in [(.6,1.3),(1.2,3.8),(2.8,2.1),(2.3,4.4),(1.7,2.8),(3.1,3.5)]:body+=n(x,y,r'$\bullet$',color='Classical',size=18)
for x in [4.5,5.55,6.6]:
 for y in [1.9,3.8]:body+=n(x,y,r'$\bullet$',color='Quantum',size=18)
body+=n(3.7,5.65,'La partenza del reticolo viene randomizzata.',w=6.9,size=11)
di=scrivi('M01','D07',body)
m.inserisci_dopo('Tre disegni attribuiscono probabilità diverse',titolo='Casualizzazione e copertura del dominio',testo='''Nel pannello sinistro i punti illustrano una possibile selezione casuale, mentre nel secondo occupano posizioni regolarmente distanziate. La regolarità può favorire la copertura del dominio, ma la sua interazione con eventuali periodicità del fenomeno deve essere valutata. Nel disegno sistematico la randomizzazione della partenza determina l’insieme delle selezioni possibili. La disposizione di una singola realizzazione documenta il campione ottenuto; le proprietà del disegno dipendono anche dalle altre realizzazioni ammissibili.''',tikz=di,didascalia='Schema illustrativo di due disegni; i punti non riproducono una raccolta reale.',richiamo='Per valutare un disegno occorre conoscere la regola che genera tutte le selezioni possibili.',origine='M01:44–46,104–105')
body=n(3.7,.3,'Componente comune del sito',color='Quantum')+r'\draw[Quantum,fill=Quantum!7] (3.7,1.4) ellipse (1.4 and .55);'+n(3.7,1.4,r'$U_g$')
for j,x in enumerate([.9,2.75,4.6,6.45],1):body+=a(3.7,2,x,3)+n(x,3.55,r'$X_{g'+str(j)+'}$',w=1.7)
body+=n(3.7,4.7,r'$X_{gi}=\mu+U_g+\varepsilon_{gi}$')+n(3.7,5.7,r'$\operatorname{Cov}(X_{gi},X_{gj})=\sigma_U^2\quad(i\ne j)$',size=11)
di=scrivi('M01','D08',body)
m.inserisci_dopo('La covarianza modifica l’informazione della media',titolo='Una componente condivisa collega i provini',testo='''Il modello rappresenta ciascuna osservazione attraverso una media comune, un contributo del sito e una componente individuale. Se i contributi dei siti sono indipendenti fra loro e indipendenti dagli errori individuali, due provini dello stesso sito condividono la varianza della componente locale. La dipendenza deriva quindi da un termine esplicito del modello. Questa costruzione permette di comprendere perché nuove stazioni possano aggiungere informazioni differenti rispetto a nuovi provini raccolti nelle stazioni già osservate.''',tikz=di,didascalia='Modello a intercetta casuale con componenti centrate e indipendenti ai rispettivi livelli.',richiamo='La covarianza comune è una conseguenza delle ipotesi del modello, da valutare sui dati e sul disegno.',origine='M01:63–66')
body=n(3.7,.2,'Informazione disponibile')
for y,lab in [(1.4,'Misura'),(3,'Censura'),(4.6,'Mancante')]:body+=n(1,y,lab,w=1.9,size=11)+linea(2.2,y,7,y,'Muted')
body+=n(5.3,1.4,r'$\bullet$',color='Classical',size=19)+r'\draw[Quantum,line width=3pt] (2.2,3)--(4.4,3);\draw[Quantum,fill=Paper,line width=1pt] (4.4,3) circle (.07);'+n(4.4,3.55,r'$L$',size=11)+n(4.6,4.6,'nessun valore disponibile',w=4.7,size=11)+n(3.7,5.75,'La censura restringe i valori ammissibili.',w=6.8,size=11)
di=scrivi('M01','D09',body)
m.inserisci_dopo('Un dato censurato fornisce un vincolo',titolo='Dalla misura puntuale all’insieme dei valori possibili',testo='''La prima riga individua un valore osservato; la seconda evidenzia un intervallo di valori compatibili con una registrazione inferiore al limite; la terza segnala l’assenza di un valore disponibile. La rappresentazione rende esplicito il diverso contenuto informativo dei tre casi. Nel secondo, il tratto colorato indica possibilità ammesse dal dato, senza attribuire loro probabilità uguali. Per costruire una distribuzione entro quell’intervallo sarebbe necessaria un’ulteriore ipotesi.''',tikz=di,didascalia='Schema di una grandezza non negativa; il cerchio aperto esclude il limite superiore L.',richiamo='Un insieme di valori ammissibili e una distribuzione di probabilità sono oggetti differenti.',origine='M01:84–85')
body=n(3.7,.3,'Scostamento dal valore di riferimento')+linea(.5,3,7,3,'Muted')+linea(3.7,1,3.7,4.9,'Quantum')
for x,y in [(3.4,2.4),(3.8,3.5),(3.6,1.8),(4,2.8)]:body+=n(x,y,r'$\bullet$',color='Classical',size=18)
for x,y in [(5.8,2.6),(6,3),(5.9,3.4),(6.1,2.2)]:body+=n(x,y,r'$\bullet$',color='Measure',size=18)
body+=n(3.6,5.4,'Riferimento',w=2.3,color='Quantum',size=11)+n(6,5.4,'Serie distorta',w=2.3,color='Measure',size=11)
di=scrivi('M01','D10',body)
m.inserisci_dopo('Ripetibilità e distorsione entrano in termini distinti',titolo='Ripetibilità e scostamento dal riferimento',testo='''Le due serie schematiche hanno una dispersione limitata, ma sono collocate diversamente rispetto al riferimento. La ripetibilità descrive la stabilità delle letture entro ciascuna serie, mentre lo scostamento riguarda la loro posizione rispetto alla grandezza di riferimento. Questa distinzione impedisce di interpretare automaticamente una bassa variabilità come prova dell’assenza di distorsione. La valutazione metrologica deve includere anche l’incertezza e la pertinenza del riferimento utilizzato.''',tikz=di,didascalia='Disposizione illustrativa: la coordinata orizzontale rappresenta la lettura; quella verticale separa le ripetizioni.',richiamo='Dispersione e scostamento vengono valutati rispetto a definizioni e condizioni specificate.',origine='M01:54–57')
m.salva()
